"use strict";(()=>{var t="https://offolab.com";chrome.runtime.onMessage.addListener((e,n,r)=>{if(e.type==="open_receipt"){let o=encodeURIComponent(e.url);chrome.tabs.create({url:`${t}/receipt?url=${o}&ext=true`})}});chrome.runtime.onMessageExternal.addListener((e,n,r)=>{e.type==="save_routine"&&e.routine&&chrome.storage.local.set({offo_routine:e.routine})});chrome.runtime.onInstalled.addListener(e=>{e.reason==="install"&&(chrome.tabs.create({url:`${t}/extension?installed=true`}),chrome.storage.local.set({enabled:!0}))});})();
